{
  "name": "getHeaders",
  "type": "function",
  "description": "Returns all message headers of the specified message, without MIME structure parsing. Throws an error if the message cannot be read, for example due to network issues. This function is significantly faster than $(ref:messages.getFull) when only the header information is required.",
  "async": "callback",
  "parameters": [
    {
      "name": "messageId",
      "$ref": "messages.MessageId"
    },
    {
      "name": "options",
      "type": "object",
      "properties": {
        "decodeHeaders": {
          "type": "boolean",
          "description": "Whether to decode RFC 2047 encoded headers. Defaults to <var>true</var>.",
          "optional": true
        }
      },
      "optional": true
    },
    {
      "type": "function",
      "name": "callback",
      "optional": true,
      "parameters": [
        {
          "$ref": "messages.HeadersDictionary"
        }
      ]
    }
  ]
},
